function hashString(s){let h=2166136261;for(let i=0;i<String(s).length;i++){h^=String(s).charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function photoUrlForStyle(style,width=1200,seed='',offset=0){const pool=photoCollections[style]||photoCollections.abstract;const index=(hashString(seed||style)+offset)%pool.length;return `https://images.unsplash.com/${pool[index]}?auto=format&fit=crop&w=${width}&q=84`}
function templatePhoto(t,width=700,offset=0){return photoUrlForStyle(t.style,width,t.id,offset)}
function thumb(t){const text=t.title.split('\n').map(esc).join('<br>');const photo=templatePhoto(t,700);const layout=t.layout||'classic';const extras=['collage','grid','moodboard'].includes(layout)?`<div class="layout-tiles ${layout}">${[0,1,2,3].map((n)=>`<i style="background-image:linear-gradient(135deg,#ffffff12,#07121d30),url('${templatePhoto(t,420,n+1)}');background-position:center"></i>`).join('')}</div>`:['polaroid','scrapbook'].includes(layout)?`<div class="layout-polaroid"><i style="background-image:url('${templatePhoto(t,420,1)}')"></i><i style="background-image:url('${templatePhoto(t,420,2)}')"></i></div>`:['dump','film'].includes(layout)?`<div class="layout-film">${[1,2,3].map(n=>`<i style="background-image:url('${templatePhoto(t,420,n)}')"></i>`).join('')}</div>`:layout==='cover'?`<div class="layout-cover"></div>`:'';return `<div class="thumb layout-${esc(layout)}" style="background-color:${t.bg}"><img class="thumb-photo" src="${photo}" alt="${esc(t.name)} photo preview" loading="lazy" decoding="async">${extras}<span class="tiny-top">${esc(t.tag)}</span><div class="thumb-title">${text}</div><span class="thumb-sub">${esc(t.sub)}</span><span class="thumb-mark">GG / STUDIO</span></div>`}
function card(t){return `<article class="template-card" tabindex="0" role="button" data-template="${t.id}" aria-label="Edit ${esc(t.name)}">${thumb(t)}<div class="template-info"><div><b>${esc(t.name)}</b><small>${esc(t.category)} · Editable</small></div><span>↗</span></div></article>`}
function renderHome(){const ids=['useful','arrival','goodfood','travel'];$('#homeTemplates').innerHTML=ids.map(id=>card(templates.find(t=>t.id===id))).join('');bindTemplateCards($('#homeTemplates'))}
function bindTemplateCards(root){root.querySelectorAll('[data-template]').forEach(el=>{const open=()=>loadTemplate(templates.find(t=>t.id===el.dataset.template));el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})});root.querySelectorAll('img.thumb-photo').forEach(img=>{img.addEventListener('load',()=>img.classList.add('photo-loaded'),{once:true});img.addEventListener('error',()=>{if(img.dataset.fallbackTried==='1')return;img.dataset.fallbackTried='1';img.src='https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=700&q=80'},{once:true})})}
function renderTemplates(){const isPhoto=t=>t.kind==='photo'||t.category==='Photo';const matches=templates.filter(t=>(state.filter==='All'||(state.filter==='Photo'?isPhoto(t):t.category===state.filter))&&`${t.name} ${t.category} ${t.tag} ${t.sub} ${t.palette||''} ${t.layout||''} ${t.style||''}`.toLowerCase().includes(state.search.toLowerCase()));const list=matches.slice(0,state.templateLimit);$('#allTemplates').innerHTML=list.map(card).join('')+(matches.length>list.length?`<div class="template-more"><p>Showing ${list.length.toLocaleString()} of ${matches.length.toLocaleString()} templates</p><button class="outline-btn" id="loadMoreTemplates">Load 120 more ↓</button></div>`:'')||'<div class="empty-projects"><h3>No matches yet</h3><p>Try another search or choose a different category.</p></div>';$('#resultCount').textContent=`${matches.length.toLocaleString()} editable designs`;bindTemplateCards($('#allTemplates'));const more=$('#loadMoreTemplates');if(more)more.onclick=()=>{state.templateLimit+=120;renderTemplates()}}
function makeLayer(type,props={}){return {id:'l'+Math.random().toString(36).slice(2,10),type,name:props.name||({text:'Text',shape:'Shape',photo:'Photo',rect:'Rectangle'}[type]||'Layer'),x:props.x??10,y:props.y??10,w:props.w??80,h:props.h??20,text:props.text??'',font:props.font||'Manrope',size:props.size??8,color:props.color||'#ffffff',weight:props.weight||700,align:props.align||'left',opacity:props.opacity??1,rotate:props.rotate||0,fill:props.fill||'#347dff',radius:props.radius??0,src:props.src||null,objectFit:props.objectFit||'cover',italic:!!props.italic,underline:!!props.underline,letter:props.letter??0,visible:props.visible!==false,templatePhotoSlot:!!props.templatePhotoSlot,filter:props.filter||'none'}}
function loadTemplate(t){if(!t)return;state.bg=t.bg;state.title=t.name;state.size='post';state.projectId=null;const layers=[];const photoCollage=!!(t.generated&&['collage','grid','moodboard','dump','film','polaroid','scrapbook'].includes(t.layout));if((t.kind==='photo'||t.category==='Photo')&&photoCollage){const frames=t.layout==='grid'?[[6,15,42,23],[52,15,42,23],[6,41,42,23],[52,41,42,23]]:t.layout==='moodboard'?[[6,15,52,37],[62,15,32,18],[62,36,32,18],[6,56,88,9]]:t.layout==='film'||t.layout==='dump'?[[6,16,27,48],[36,16,27,48],[66,16,28,48]]:t.layout==='polaroid'?[[8,18,38,46],[54,20,38,44]]:t.layout==='scrapbook'?[[7,16,42,27],[53,15,39,23],[13,45,35,18],[54,42,38,21]]:[[6,16,50,28],[59,16,35,24],[15,46,32,17],[53,43,41,20]];frames.forEach((f,i)=>layers.push(makeLayer('photo',{name:`Photo frame ${i+1}`,x:f[0],y:f[1],w:f[2],h:f[3],templatePhotoSlot:true,fill:t.bg,src:photoUrlForStyle(t.style,800,t.id,i)})));}else if(t.style==='mountain'||t.category==='Photo'||t.kind==='photo'){layers.push(makeLayer('photo',{name:'Photo background',x:0,y:0,w:100,h:100,templatePhotoSlot:true,fill:t.bg,src:photoUrlForStyle(t.style,1200,t.id)}));layers.push(makeLayer('shape',{name:'Photo contrast overlay',x:0,y:0,w:100,h:100,fill:'#07111d',radius:0,opacity:.12}));}else if(t.style==='product'){layers.push(makeLayer('shape',{name:'Accent shape',x:56,y:23,w:39,h:44,fill:t.accent,radius:45,opacity:.7}));layers.push(makeLayer('shape',{name:'Product block',x:58,y:34,w:29,h:36,fill:'#101a26',radius:4,opacity:.95}));}else if(t.style==='sunset'){layers.push(makeLayer('shape',{name:'Sun shape',x:55,y:22,w:55,h:45,fill:t.accent,radius:50,opacity:.65}));}else if(t.style==='food'){layers.push(makeLayer('shape',{name:'Accent plate',x:52,y:30,w:48,h:48,fill:t.accent,radius:50,opacity:.5}));layers.push(makeLayer('shape',{name:'Plate',x:61,y:38,w:32,h:32,fill:'#f2dfc5',radius:50,opacity:.9}));}else if(t.style==='minimal'){state.bg='#e8e0d1'}else{layers.push(makeLayer('shape',{name:'Accent panel',x:56,y:24,w:35,h:48,fill:t.accent,radius:3,opacity:.18}));}
layers.push(makeLayer('text',{name:'Eyebrow',x:8,y:7,w:80,h:5,text:t.tag,font:'DM Sans',size:1.5,color:t.accent,weight:700,letter:1.6}));
const titleFrame=t.generated&&['collage','grid','moodboard','dump','film','polaroid','scrapbook'].includes(t.layout)?{x:8,y:76,w:84,h:13}:t.layout==='cover'?{x:8,y:30,w:84,h:36}:t.layout==='type'?{x:7,y:29,w:88,h:38}:t.layout==='editorial'?{x:8,y:39,w:84,h:31}:{x:8,y:27,w:84,h:35};layers.push(makeLayer('text',{name:'Headline',...titleFrame,text:t.title,font:'Manrope',size:t.generated&&['collage','grid','moodboard','dump','film','polaroid','scrapbook'].includes(t.layout)?5.8:9.2,color:photoCollage?(t.textColor||'#ffffff'):((t.kind==='photo'||t.category==='Photo')?'#ffffff':t.style==='minimal'?'#1d3347':'#ffffff'),weight:800,letter:-.3}));layers.push(makeLayer('text',{name:'Supporting text',x:8,y:66,w:82,h:7,text:t.sub,font:'DM Sans',size:2.2,color:photoCollage?(t.textColor||'#f4f1eb'):(t.kind==='photo'||t.category==='Photo'?'#f4f1eb':t.style==='minimal'?'#33485a':'#dbe8f7'),weight:500}));layers.push(makeLayer('text',{name:'Brand mark',x:8,y:91,w:80,h:4,text:'GRAPHICS GENIX  /  STUDIO',font:'DM Sans',size:1.4,color:photoCollage?(t.textColor||'#f4f1eb'):(t.kind==='photo'||t.category==='Photo'?'#dbe8f7':t.style==='minimal'?'#33485a':'#9db5d1'),weight:700,letter:1.2}));state.layers=layers;state.selected=layers.find(l=>l.name==='Headline')?.id;state.history=[];state.future=[];go('editor');renderEditor();pushHistory();toast('Template opened — every text layer is editable.')}
function createBlank(size='post'){state.size=size;state.bg='#0b1928';state.title='Untitled design';state.projectId=null;state.layers=[makeLayer('text',{name:'Headline',x:9,y:32,w:82,h:22,text:'Your big idea.\nStarts here.',size:8.5,color:'#ffffff',weight:800}),makeLayer('text',{name:'Supporting text',x:9,y:61,w:75,h:10,text:'Add a few words that make it yours.',size:2.4,color:'#a9bdd6',weight:500}),makeLayer('text',{name:'Brand mark',x:9,y:91,w:80,h:4,text:'GRAPHICS GENIX  /  STUDIO',size:1.4,color:'#8aa7ca',letter:1.2})];state.selected=state.layers[0].id;state.history=[];state.future=[];go('editor');renderEditor();pushHistory();toast('Blank canvas created.')}
function pushHistory(){const snap=JSON.stringify({layers:state.layers,bg:state.bg,size:state.size,title:state.title});if(state.history[state.history.length-1]!==snap){state.history.push(snap);if(state.history.length>60)state.history.shift();state.future=[]}updateUndoRedo();saveCurrent()}
function restore(snap){const s=JSON.parse(snap);state.layers=s.layers;state.bg=s.bg;state.size=s.size;state.title=s.title;state.selected=null;renderEditor();updateUndoRedo()}
function undo(){if(state.history.length<2)return;state.future.push(state.history.pop());restore(state.history[state.history.length-1]);toast('Undo')}
function redo(){if(!state.future.length)return;const s=state.future.pop();state.history.push(s);restore(s);toast('Redo')}
function saveCurrent(){try{localStorage.setItem('ggx-studio-current',JSON.stringify({layers:state.layers,bg:state.bg,size:state.size,title:state.title,projectId:state.projectId,updated:Date.now()}))}catch(e){}}
function renderEditor(){const c=$('#canvas');const size=sizes[state.size]||sizes.post;c.style.aspectRatio=`${size.w}/${size.h}`;c.style.background=state.bg;c.style.transform=`scale(${state.zoom})`;$('#canvasSize').textContent=size.label;$('#projectTitle').textContent=state.title;$('#sizeSelect').value=state.size;$('#bgColor').value=state.bg;$('#bgHex').textContent=state.bg.toUpperCase();$('#zoomLabel').textContent=`${Math.round(state.zoom*100)}%`;c.innerHTML='';state.layers.forEach(l=>{if(!l.visible)return;const el=document.createElement('div');el.className=`design-object ${l.type==='text'?'text-object':''}${l.id===state.selected?' selected':''}`;el.dataset.id=l.id;Object.assign(el.style,{left:l.x+'%',top:l.y+'%',width:l.w+'%',height:l.h+'%',opacity:l.opacity,transform:`rotate(${l.rotate}deg)`,zIndex:state.layers.indexOf(l)+1});if(l.type==='text'){el.textContent=l.text;Object.assign(el.style,{fontFamily:l.font+', sans-serif',fontSize:l.size+'cqw',fontWeight:l.weight,color:l.color,textAlign:l.align,letterSpacing:l.letter+'px',fontStyle:l.italic?'italic':'normal',textDecoration:l.underline?'underline':'none',lineHeight:'1.04',display:'flex',alignItems:'flex-start',justifyContent:l.align==='center'?'center':l.align==='right'?'flex-end':'flex-start',padding:'0',overflow:'visible'}); }else if(l.type==='photo'){el.style.backgroundColor=l.fill||'#142a3f';el.style.overflow='hidden';if(l.src){el.style.backgroundImage=`url("${l.src}")`;el.style.backgroundPosition='center';el.style.backgroundSize='cover';el.style.backgroundRepeat='no-repeat';const img=document.createElement('img');img.crossOrigin='anonymous';img.alt='Design photo';img.decoding='async';img.style.filter=l.filter;img.onload=()=>img.classList.add('photo-loaded');img.onerror=()=>{img.remove();el.classList.add('photo-load-failed')};img.src=l.src;el.append(img)}else{el.innerHTML='<div class="photo-mountain"></div>';el.style.backgroundImage=`linear-gradient(135deg,${l.fill||'#173a51'},#08121f)`}}else{el.style.background=l.fill;el.style.borderRadius=l.radius+'%';el.style.border=l.type==='rect'?'1px solid #ffffff55':'none'}el.addEventListener('pointerdown',e=>beginDrag(e,l));el.addEventListener('click',e=>{e.stopPropagation();selectLayer(l.id)});c.append(el)});c.onclick=e=>{if(e.target===c){state.selected=null;renderEditor()}};renderLayerList();renderProps();updateUndoRedo();}
let drag=null;function beginDrag(e,l){if(e.button!==undefined&&e.button!==0)return;e.stopPropagation();if(state.selected!==l.id){state.selected=l.id;renderEditor()}const el=e.currentTarget;drag={id:l.id,startX:e.clientX,startY:e.clientY,x:l.x,y:l.y,moved:false};el.setPointerCapture?.(e.pointerId);el.addEventListener('pointermove',moveDrag);el.addEventListener('pointerup',endDrag,{once:true});el.addEventListener('pointercancel',endDrag,{once:true});function moveDrag(ev){if(!drag)return;const rect=$('#canvas').getBoundingClientRect();if(!rect.width||!rect.height)return;const dx=(ev.clientX-drag.startX)/rect.width*100,dy=(ev.clientY-drag.startY)/rect.height*100;if(Math.abs(dx)+Math.abs(dy)>.2)drag.moved=true;l.x=clamp(drag.x+dx,0,100-l.w);l.y=clamp(drag.y+dy,0,100-l.h);el.style.left=l.x+'%';el.style.top=l.y+'%'}function endDrag(){if(drag?.moved){pushHistory();renderLayerList();renderProps()}drag=null;el.removeEventListener('pointermove',moveDrag)}}
function clamp(n,min,max){return Math.min(max,Math.max(min,Number(n)||0))}
function selectLayer(id){state.selected=id;renderEditor()}
function renderLayerList(){const box=$('#layerList');box.innerHTML='';[...state.layers].reverse().forEach(l=>{const row=document.createElement('div');row.className='layer-row'+(l.id===state.selected?' active':'');row.innerHTML=`<span>${l.type==='text'?'T':l.type==='photo'?'▧':'◧'}</span><span class="layer-name">${esc(l.name||l.type)}</span><button type="button" aria-label="${l.visible?'Hide':'Show'} layer">${l.visible?'◉':'○'}</button>`;row.addEventListener('click',e=>{if(e.target.tagName==='BUTTON'){l.visible=!l.visible;pushHistory();renderEditor();return}selectLayer(l.id)});box.append(row)});$('#layerCount').textContent=`${state.layers.length} object${state.layers.length===1?'':'s'}`}
function renderProps(){const l=state.layers.find(o=>o.id===state.selected);$('#designProps').classList.toggle('hidden',!!l);$('#objectProps').classList.toggle('hidden',!l);$('#propTitle').textContent=l?l.name:'Design';$('#selectedHint').textContent=l?`${l.name} selected`:'Select an object to get started';if(!l)return;const p=$('#objectProps');let html='';if(l.type==='text'){html+=`<label>TEXT</label><textarea id="objText" rows="4">${esc(l.text)}</textarea><div class="two-fields"><div><label>Font</label><select id="objFont"><option ${l.font==='Manrope'?'selected':''}>Manrope</option><option ${l.font==='DM Sans'?'selected':''}>DM Sans</option><option ${l.font==='Georgia'?'selected':''}>Georgia</option><option ${l.font==='Arial'?'selected':''}>Arial</option></select></div><div><label>Size</label><input id="objSize" type="number" min=".5" max="24" step=".2" value="${l.size}"></div></div><label>TEXT COLOR</label><input id="objColor" type="color" value="${safeColor(l.color)}"><div class="two-fields"><div><label>Weight</label><select id="objWeight"><option value="400" ${l.weight==400?'selected':''}>Regular</option><option value="500" ${l.weight==500?'selected':''}>Medium</option><option value="700" ${l.weight==700?'selected':''}>Bold</option><option value="800" ${l.weight==800?'selected':''}>Extra bold</option></select></div><div><label>Align</label><select id="objAlign"><option value="left" ${l.align==='left'?'selected':''}>Left</option><option value="center" ${l.align==='center'?'selected':''}>Center</option><option value="right" ${l.align==='right'?'selected':''}>Right</option></select></div></div><div class="two-fields"><div><label>Letter spacing</label><input id="objLetter" type="number" min="-3" max="12" step=".2" value="${l.letter}"></div><div><label>Opacity</label><input id="objOpacity" type="number" min="0" max="1" step=".1" value="${l.opacity}"></div></div>`}else if(l.type==='photo'){html+=`<p style="font-size:10px;color:#8195b0;line-height:1.6">${l.src?'Photo layer selected. Replace the image or adjust its frame.':'Photo placeholder. Add an image to fill this frame.'}</p><button class="outline-btn full" id="replacePhoto">↻ Replace photo</button><label>FRAME COLOR</label><input id="objFill" type="color" value="${safeColor(l.fill)}"><label>Opacity</label><input id="objOpacity" type="number" min="0" max="1" step=".1" value="${l.opacity}">`}else{html+=`<label>FILL COLOR</label><input id="objFill" type="color" value="${safeColor(l.fill)}"><label>ROUNDING (%)</label><input id="objRadius" type="number" min="0" max="50" value="${l.radius}"><label>OPACITY</label><input id="objOpacity" type="number" min="0" max="1" step=".1" value="${l.opacity}">`}
html+=`<div class="field-label">POSITION & SIZE (%)</div><div class="two-fields"><div><label>Left</label><input id="objX" type="number" min="0" max="100" step=".5" value="${l.x}"></div><div><label>Top</label><input id="objY" type="number" min="0" max="100" step=".5" value="${l.y}"></div><div><label>Width</label><input id="objW" type="number" min="1" max="100" step=".5" value="${l.w}"></div><div><label>Height</label><input id="objH" type="number" min="1" max="100" step=".5" value="${l.h}"></div></div><label>ROTATION</label><input id="objRotate" type="number" min="-180" max="180" value="${l.rotate}"><button class="danger-btn" id="deleteLayer">Delete this layer</button>`;p.innerHTML=`<div class="object-fields">${html}</div>`;const bind=(id,fn,ev='change')=>{const el=$('#'+id);if(el)el.addEventListener(ev,()=>{fn(el);renderCanvasOnly();if(ev==='change'){pushHistory();renderLayerList()}})};bind('objText',el=>l.text=el.value,'input');bind('objFont',el=>l.font=el.value);bind('objSize',el=>l.size=clamp(el.value,.5,24));bind('objColor',el=>l.color=el.value);bind('objWeight',el=>l.weight=Number(el.value));bind('objAlign',el=>l.align=el.value);bind('objLetter',el=>l.letter=clamp(el.value,-3,12));bind('objOpacity',el=>l.opacity=clamp(el.value,0,1));bind('objFill',el=>l.fill=el.value);bind('objRadius',el=>l.radius=clamp(el.value,0,50));bind('objX',el=>l.x=clamp(el.value,0,100-l.w));bind('objY',el=>l.y=clamp(el.value,0,100-l.h));bind('objW',el=>l.w=clamp(el.value,1,100-l.x));bind('objH',el=>l.h=clamp(el.value,1,100-l.y));bind('objRotate',el=>l.rotate=clamp(el.value,-180,180));$('#deleteLayer')?.addEventListener('click',()=>{state.layers=state.layers.filter(x=>x.id!==l.id);state.selected=null;pushHistory();renderEditor();toast('Layer deleted')});$('#replacePhoto')?.addEventListener('click',()=>{pendingPhotoLayer=l.id;$('#photoInput').click()})}
function safeColor(c){return /^#[0-9a-f]{6}$/i.test(c||'')?c:'#ffffff'}function renderCanvasOnly(){const l=state.layers.find(o=>o.id===state.selected);if(!l)return;const el=$(`#canvas [data-id="${l.id}"]`);if(!el){renderEditor();return}Object.assign(el.style,{left:l.x+'%',top:l.y+'%',width:l.w+'%',height:l.h+'%',opacity:l.opacity,transform:`rotate(${l.rotate}deg)`});if(l.type==='text'){el.textContent=l.text;Object.assign(el.style,{fontFamily:l.font+', sans-serif',fontSize:l.size+'cqw',fontWeight:l.weight,color:l.color,textAlign:l.align,letterSpacing:l.letter+'px',fontStyle:l.italic?'italic':'normal'})}else if(l.type==='shape'||l.type==='rect'){el.style.background=l.fill;el.style.borderRadius=l.radius+'%'}}
let pendingPhotoLayer=null;function addText(){const l=makeLayer('text',{name:'New text',x:10,y:43,w:80,h:14,text:'Type something…',size:6,color:'#ffffff',weight:700});state.layers.push(l);state.selected=l.id;pushHistory();renderEditor();toast('Text layer added')}
function addShape(){const l=makeLayer('shape',{name:'Accent shape',x:62,y:28,w:25,h:20,fill:'#347dff',radius:8,opacity:.9});state.layers.push(l);state.selected=l.id;pushHistory();renderEditor();toast('Shape added')}
function openPhoto(){pendingPhotoLayer=null;$('#photoInput').click()}
function handlePhoto(file){if(!file||!file.type.startsWith('image/')){toast('Please choose an image file.');return}if(file.size>20*1024*1024){toast('Please choose an image under 20 MB.');return}const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{if(pendingPhotoLayer){const l=state.layers.find(x=>x.id===pendingPhotoLayer);if(l){l.src=url;l.name='Photo';l.templatePhotoSlot=false;l.fill='#18384e';state.selected=l.id;pushHistory();renderEditor();toast('Photo replaced. Other layers stayed in place.')}}else if(state.view==='photo'){state.photoURL=url;state.photoImage=img;$('#photoPreview').src=url;$('#photoPreview').hidden=false;$('#photoEmpty').hidden=true;applyPhotoFilters();}else{const l=makeLayer('photo',{name:'Photo',x:10,y:18,w:80,h:65,src:url,fill:'#19364c'});state.layers.push(l);state.selected=l.id;pushHistory();renderEditor();toast('Photo added as a new layer.')}pendingPhotoLayer=null};img.onerror=()=>toast('That image could not be opened. Try another file.');img.src=url}
function changeSize(size){state.size=size;pushHistory();renderEditor();toast('Canvas size updated')}
function openExport(){if(!state.layers.length){toast('Add something to your canvas first.');return}$('#exportModal').classList.remove('hidden')}
async function drawDesign(){const sz=sizes[state.size]||sizes.post;const canvas=document.createElement('canvas');canvas.width=sz.w;canvas.height=sz.h;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Canvas export is unavailable');ctx.fillStyle=state.bg;ctx.fillRect(0,0,sz.w,sz.h);for(const l of state.layers){if(!l.visible)continue;ctx.save();ctx.globalAlpha=l.opacity;const x=l.x/100*sz.w,y=l.y/100*sz.h,w=l.w/100*sz.w,h=l.h/100*sz.h;ctx.translate(x+w/2,y+h/2);ctx.rotate(l.rotate*Math.PI/180);if(l.type==='text'){ctx.fillStyle=l.color;ctx.textBaseline='top';ctx.textAlign=l.align;ctx.font=`${l.italic?'italic ':''}${l.weight} ${Math.max(8,l.size/100*sz.w)}px "${l.font}"`;ctx.letterSpacing=(l.letter||0)+'px';const lines=String(l.text).split('\n');const lineH=Math.max(8,l.size/100*sz.w*1.04);const tx=l.align==='left'?-w/2:l.align==='center'?0:w/2;lines.forEach((line,i)=>ctx.fillText(line,tx,-h/2+i*lineH,w));ctx.restore()}else if(l.type==='photo'&&l.src){try{const im=await new Promise((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.onload=()=>resolve(image);image.onerror=reject;image.src=l.src});ctx.beginPath();ctx.rect(-w/2,-h/2,w,h);ctx.clip();ctx.filter=l.filter||'none';ctx.drawImage(im,-w/2,-h/2,w,h)}catch(err){ctx.fillStyle=l.fill||'#17384d';ctx.fillRect(-w/2,-h/2,w,h)}ctx.restore()}else{ctx.fillStyle=l.fill||'#347dff';const r=Math.min(w,h)*Math.min(50,l.radius||0)/100;ctx.beginPath();if(ctx.roundRect)ctx.roundRect(-w/2,-h/2,w,h,r);else ctx.rect(-w/2,-h/2,w,h);ctx.fill();ctx.restore()}}return canvas}
async function exportDesign(){try{const c=await drawDesign();const mime=state.exportFormat==='jpg'?'image/jpeg':'image/png';const blob=await new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(new Error('Could not create image')),mime,Number($('#exportQuality').value)||.95));const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${(state.title||'graphics-genix-design').trim().replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'graphics-genix-design'}.${state.exportFormat}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);$('#exportModal').classList.add('hidden');toast('Your design has been exported.')}catch(e){console.error(e);toast('Export failed. Try removing the photo and exporting again.')}}
function saveProject(){const saved=JSON.parse(localStorage.getItem('ggx-studio-projects')||'[]');const item={id:state.projectId||'p'+Date.now(),title:state.title,bg:state.bg,size:state.size,layers:state.layers,updated:Date.now()};const idx=saved.findIndex(x=>x.id===item.id);if(idx>=0)saved[idx]=item;else saved.unshift(item);try{localStorage.setItem('ggx-studio-projects',JSON.stringify(saved.slice(0,40)));state.projectId=item.id;saveCurrent();toast('Project saved in this browser.')}catch(e){toast('Browser storage is full. Export your design to keep a copy.')}}
function renderProjects(){let saved=[];try{saved=JSON.parse(localStorage.getItem('ggx-studio-projects')||'[]')}catch(e){};const grid=$('#projectsGrid');if(!saved.length){grid.innerHTML='<div class="empty-projects"><h3>Your next idea starts here.</h3><p>Save a design from the editor and it will appear here.</p><button class="primary" id="projectsNew">＋ Create a design</button></div>';$('#projectsNew').onclick=()=>go('templates');return}grid.innerHTML=saved.map(p=>{const t={id:p.id,name:p.title||'Untitled design',category:'Saved project',tag:'YOUR PROJECT',bg:p.bg||'#10283a',title:(p.layers.find(l=>l.type==='text')||{}).text||'Your design',sub:'Saved locally',accent:'#9ccaff',style:'abstract'};return `<article class="template-card" data-project="${esc(p.id)}">${thumb(t)}<div class="template-info"><div><b>${esc(p.title||'Untitled design')}</b><small>Saved project</small></div><span>↗</span></div></article>`}).join('');grid.querySelectorAll('[data-project]').forEach(el=>el.onclick=()=>{const p=saved.find(x=>x.id===el.dataset.project);if(!p)return;state.layers=p.layers;state.bg=p.bg;state.size=p.size;state.title=p.title;state.projectId=p.id;state.selected=null;state.history=[];state.future=[];go('editor');renderEditor();pushHistory()})}
function applyPhotoFilters(){if(!state.photoImage)return;const a=state.photoAdjust;$('#photoPreview').style.filter=`brightness(${a.brightness}%) contrast(${a.contrast}%) saturate(${a.saturation}%) sepia(${Math.max(0,a.warmth)/100}) hue-rotate(${Math.min(0,a.warmth)*.5}deg) opacity(${100-a.fade}%) grayscale(${state.photoPreset==='mono'?1:0}) ${state.photoPreset==='cinematic'?'contrast(1.12) saturate(.78)':state.photoPreset==='vivid'?'saturate(1.35)':''}`;for(const k of Object.keys(a)){const output=$('#'+k+'Val');if(output)output.textContent=k==='brightness'||k==='contrast'||k==='saturation'?`${a[k]}%`:k==='fade'?`${a[k]}%`:String(a[k])}}
function downloadEditedPhoto(){if(!state.photoImage){toast('Choose a photo first.');return}const im=state.photoImage;const c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;const ctx=c.getContext('2d');const a=state.photoAdjust;ctx.filter=`brightness(${a.brightness}%) contrast(${a.contrast}%) saturate(${a.saturation}%) sepia(${Math.max(0,a.warmth)/100}) hue-rotate(${Math.min(0,a.warmth)*.5}deg) opacity(${100-a.fade}%) grayscale(${state.photoPreset==='mono'?1:0}) ${state.photoPreset==='cinematic'?'contrast(1.12) saturate(.78)':state.photoPreset==='vivid'?'saturate(1.35)':''}`;ctx.drawImage(im,0,0);c.toBlob(blob=>{if(!blob){toast('Could not export this photo.');return}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='graphics-genix-photo.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Edited photo downloaded.')},'image/jpeg',.94)}

// Tool rail actions: every visible editor tool has a working action.
$$('[data-tool]').forEach(btn=>btn.addEventListener('click',()=>{
  const tool=btn.dataset.tool;$$('[data-tool]').forEach(x=>x.classList.toggle('active',x===btn));
  if(tool==='select'){toast('Select an object on the canvas.');return}
  if(tool==='text'){addText();return}
  if(tool==='shape'){addShape();return}
  if(tool==='photo'){
    const selected=state.layers.find(l=>l.id===state.selected);
    if(selected&&selected.type==='photo'){pendingPhotoLayer=selected.id;$('#photoInput').click()}
    else openPhoto();return
  }
  if(tool==='background'){$('#bgColor').focus();$('#bgColor').click();toast('Choose a canvas background colour.');return}
}));
