// Navigation and primary actions
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.goto)));$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#startProject').onclick=()=>go('templates');$('#blankDesign').onclick=()=>createBlank();$$('[data-size]').forEach(b=>b.onclick=()=>createBlank(b.dataset.size==='custom'?'custom':b.dataset.size));$('#templateSearch').addEventListener('input',e=>{state.search=e.target.value;state.templateLimit=120;renderTemplates()});$('#filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;state.filter=b.dataset.filter;state.templateLimit=120;$$('.filter').forEach(x=>x.classList.toggle('active',x===b));renderTemplates()});
$('#undo').onclick=undo;$('#redo').onclick=redo;$('#addTextTop').onclick=addText;$('#addTextProp').onclick=addText;$('#addShapeProp').onclick=addShape;$('#uploadProp').onclick=openPhoto;$('#photoInput').addEventListener('change',e=>{handlePhoto(e.target.files[0]);e.target.value=''});$('#sizeSelect').onchange=e=>changeSize(e.target.value);$('#bgColor').oninput=e=>{$('#canvas').style.background=e.target.value;$('#bgHex').textContent=e.target.value.toUpperCase();state.bg=e.target.value};$('#bgColor').onchange=()=>{pushHistory();renderEditor()};$('#clearSelection').onclick=()=>{state.selected=null;renderEditor()};$('#zoomIn').onclick=()=>{state.zoom=clamp(state.zoom+.1,.5,1.5);renderEditor()};$('#zoomOut').onclick=()=>{state.zoom=clamp(state.zoom-.1,.5,1.5);renderEditor()};$('#projectTitle').addEventListener('input',e=>{state.title=e.target.textContent;saveCurrent()});$('#projectTitle').addEventListener('blur',()=>pushHistory());$('#saveProjectBtn').onclick=saveProject;$('#exportBtn').onclick=openExport;$('#exportTop').onclick=()=>state.view==='editor'?openExport():go('editor');$('#closeExport').onclick=()=>$('#exportModal').classList.add('hidden');$('#exportModal').addEventListener('click',e=>{if(e.target===$('#exportModal'))$('#exportModal').classList.add('hidden')});$$('.format').forEach(b=>b.onclick=()=>{state.exportFormat=b.dataset.format;$$('.format').forEach(x=>x.classList.toggle('active',x===b))});$('#confirmExport').onclick=exportDesign;
$('#photoUploadBtn').onclick=()=>$('#photoInputStandalone').click();$('#photoEmptyBtn').onclick=()=>$('#photoInputStandalone').click();$('#photoInputStandalone').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>20*1024*1024){toast('Choose an image under 20 MB.');return}const url=URL.createObjectURL(f),img=new Image();img.onload=()=>{state.photoURL=url;state.photoImage=img;$('#photoPreview').src=url;$('#photoPreview').hidden=false;$('#photoEmpty').hidden=true;applyPhotoFilters()};img.src=url;e.target.value=''};['brightness','contrast','saturation','warmth','fade'].forEach(k=>$('#'+k).addEventListener('input',e=>{state.photoAdjust[k]=Number(e.target.value);applyPhotoFilters()}));$('#resetPhoto').onclick=()=>{state.photoAdjust={brightness:100,contrast:100,saturation:100,warmth:0,fade:0};state.photoPreset='original';['brightness','contrast','saturation','warmth','fade'].forEach(k=>$('#'+k).value=state.photoAdjust[k]);applyPhotoFilters()};$$('[data-preset]').forEach(b=>b.onclick=()=>{state.photoPreset=b.dataset.preset;if(state.photoPreset==='cinematic'){state.photoAdjust={...state.photoAdjust,contrast:115,saturation:78,warmth:8}}else if(state.photoPreset==='vivid'){state.photoAdjust={...state.photoAdjust,contrast:108,saturation:145,warmth:0}}else if(state.photoPreset==='mono'){state.photoAdjust={...state.photoAdjust,saturation:0}}else state.photoAdjust={brightness:100,contrast:100,saturation:100,warmth:0,fade:0};for(const k of Object.keys(state.photoAdjust))$('#'+k).value=state.photoAdjust[k];applyPhotoFilters()});$('#downloadPhoto').onclick=downloadEditedPhoto;
// Keyboard shortcuts are scoped away from editable fields.
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();go('templates');$('#templateSearch').focus()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable){e.preventDefault();e.shiftKey?redo():undo()}if(e.key==='Escape'){$('#exportModal').classList.add('hidden');$('#sidebar').classList.remove('open')}});
