$('#mobileUndo')?.addEventListener('click',undo);$('#mobileRedo')?.addEventListener('click',redo);
hydrateTemplateFilters();renderHome();renderTemplates();$('#sizeSelect').value=state.size;try{const current=JSON.parse(localStorage.getItem('ggx-studio-current')||'null');if(current&&current.layers&&current.layers.length){state.layers=current.layers;state.bg=current.bg||state.bg;state.size=current.size||'post';state.title=current.title||'Untitled design';state.projectId=current.projectId||null;state.history=[];state.future=[];}}catch(e){}renderEditor();pushHistory();
